import sqlite3

def sincronizar_dados(api_itens, banco_itens):
    conexao = sqlite3.connect(':memory:')
    cursor = conexao.cursor()
    cursor.execute('CREATE TABLE clientes (id INTEGER PRIMARY KEY, nome TEXT, pontos INTEGER)')
    cursor.executemany(
        'INSERT INTO clientes (id, nome, pontos) VALUES (?, ?, ?)',
        banco_itens,
    )
    conexao.commit()

    for item in api_itens:
        existe = cursor.execute(
            'SELECT 1 FROM clientes WHERE id = ?',
            (item['id'],),
        ).fetchone()
        if existe:
            cursor.execute(
                'UPDATE clientes SET nome = ?, pontos = ? WHERE id = ?',
                (item['nome'], item['pontos'], item['id']),
            )
        else:
            cursor.execute(
                'INSERT INTO clientes (id, nome, pontos) VALUES (?, ?, ?)',
                (item['id'], item['nome'], item['pontos']),
            )
    conexao.commit()
    return cursor.execute('SELECT id, nome, pontos FROM clientes ORDER BY id').fetchall()

